style.css:
@-moz-document domain("comick.io") {
body {
    background-image: url("https://img1.wallspic.com/crops/2/1/8/5/6/165812/165812-atmosphere-geometry-mathematics-purple-violet-2560x1440.jpg");
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-size: cover;
    background-position: center center;
    position: relative;
    z-index: 0;
  }

  body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.4);  /* Change 0.4 for more/less dim */
    z-index: -1;
    pointer-events: none;
  }

.dark\:scrollbox-dark {
  background: none !important;
  background-color: transparent !important;
  background-image: none !important;
}

/* continue button */
.btn-primary {
  background-image: url("https://i.postimg.cc/66fQx8nG/digital-neural-cascade.jpg");
  background-size: cover;
  background-position: center;
  color: white;
  border: none;
}

/* The menu at bottom and top*/
.dark\:border-gray-700 {

}

/* Tags */
.dark\:bg-gray-750 {
  background-color: transparent !important;
  box-shadow: none !important;
}

/* chapter list */
.dark\:bg-gray-800 {
  background-color: transparent !important; 
}
/* reading button */
#__next > main > div.padding-safe-left.mb-64.md\:pb-0 > div.xl\:max-w-screen-xl.mx-auto.space-y-20.divide-gray-500.mt-1.md\:mt-2.md\:pt-2.lg\:pt-3.xl\:pt-4 > div.grid.grid-cols-2.md\:grid-cols-3.max-xl\:px-1 > div.col-span-3.md\:col-span-2.my-8 > div.flex.items-center.w-full.md\:max-w-md.xl\:max-w-xl.space-x-3 > select {
  background-image: url('https://i.ytimg.com/vi/qPbS_mBFAkg/hq720.jpg?sqp=-oaymwEXCK4FEIIDSFryq4qpAwkIARUAAIhCGAE=&rs=AOn4CLCYI4rPgEZLOkjyDcB_E7rUK7UEPg'); /* ? Replace with your actual image path */
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-color: #1a1a1a !important;
  border: none;
  padding-left: 1rem;
}
}
